import perceivo

_ON_MISSING = ("list_available", "error")
_FALSY = ("false", "0", "no", "off", "")


def _flag(value) -> bool:
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    return str(value).strip().lower() not in _FALSY


def _tool_summary(tool) -> dict:
    if not isinstance(tool, dict):
        return {"name": str(tool), "description": "", "input_schema": {}}
    return {
        "name": str(tool.get("name", "")),
        "description": str(tool.get("description", "") or ""),
        "input_schema": tool.get("input_schema") or {},
    }


def _result(
    success: bool, tool_name: str, result: dict, error: str = ""
) -> perceivo.primitives.ToolOutput:
    return perceivo.primitives.ToolOutput(
        response_data={"success": success, "tool_name": tool_name, "result": result, "error": error}
    )


@perceivo.tool
async def mcp_tool_runner(input: perceivo.primitives.ToolInput) -> perceivo.primitives.ToolOutput:
    """Call one tool on the organization's MCP server, or list the tools it offers.

    The tool name comes from request_data.tool_name, else the Default Tool
    parameter. A tool that reports an error, or a name the server does not
    offer, is returned as data with success false so the caller can recover;
    an MCP server that is not running, or a bad setting, fails the run.
    """
    request = input.request_data or {}
    if not isinstance(request, dict):
        raise ValueError("request_data must be an object.")

    on_missing = str(
        perceivo.params.get("list_on_empty", "list_available") or "list_available"
    ).strip()
    if on_missing not in _ON_MISSING:
        raise ValueError(
            f"When No Tool Is Given is '{on_missing}'; use one of {', '.join(_ON_MISSING)}."
        )

    arguments = request.get("arguments")
    if arguments is None:
        arguments = {}
    if not isinstance(arguments, dict):
        raise ValueError("request_data.arguments must be an object of the tool's arguments.")

    tool_name = str(
        request.get("tool_name") or perceivo.params.get("default_tool_name", "") or ""
    ).strip()
    list_only = _flag(request.get("list_tools"))
    if not tool_name and not list_only:
        if on_missing == "error":
            raise ValueError(
                "No tool to call: set request_data.tool_name or the Default Tool parameter."
            )
        list_only = True

    mcp = await perceivo.cluster.mcp.connect()
    if not await mcp.is_available():
        raise RuntimeError(
            "The organization's MCP server is not running. Start it in Infrastructure before using this tool."
        )

    tools = [_tool_summary(t) for t in await mcp.list_tools()]
    if list_only:
        perceivo.log.info("Listed MCP tools", count=len(tools))
        return _result(True, "", {"tools": tools})

    available = sorted(t["name"] for t in tools)
    if tool_name not in available:
        perceivo.log.warning("MCP tool not found", tool_name=tool_name, available=len(available))
        return _result(
            False,
            tool_name,
            {"available_tools": available},
            f"Tool '{tool_name}' is not offered by the MCP server.",
        )

    try:
        outcome = await mcp.call_tool(tool_name, arguments)
    except RuntimeError:
        raise
    except Exception as exc:
        perceivo.log.warning("MCP tool failed", tool_name=tool_name, error_type=type(exc).__name__)
        return _result(False, tool_name, {}, f"{type(exc).__name__}: {exc}")

    result = outcome if isinstance(outcome, dict) else {"value": outcome}
    perceivo.log.info("Called MCP tool", tool_name=tool_name)
    return _result(True, tool_name, result)
